const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const memphisArea = ee.Geometry.Polygon([[
    [-90.3, 35.0], [-89.8, 35.0], [-89.8, 35.3], [-90.3, 35.3], [-90.3, 35.0]
  ]]);

  const sept2021 = ['2021-09-01', '2021-09-30'];
  const sept2023 = ['2023-09-01', '2023-09-30'];

  // 2. Data Acquisition - Sentinel-2
  function getWaterArea(dateRange, year) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(memphisArea)
      .filterDate(dateRange[0], dateRange[1])
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    const size = collection.size().getInfo();
    console.log(`${year} Images: ${size}`);

    if (size === 0) {
      console.log(`No Sentinel-2 data for ${year}, trying Landsat`);
      collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(memphisArea)
        .filterDate(dateRange[0], dateRange[1])
        .filter(ee.Filter.lt('CLOUD_COVER', 30));

      const landsatSize = collection.size().getInfo();
      console.log(`${year} Landsat Images: ${landsatSize}`);
      if (landsatSize === 0) return null;

      // Use median composite for Landsat
      const image = collection.median();
      // Calculate NDWI for Landsat: (Green - SWIR1)/(Green + SWIR1)
      const ndwi = image.normalizedDifference(['SR_B3', 'SR_B6']);
      const water = ndwi.gt(0.0);
      return water;
    }

    // Use median composite for Sentinel-2
    const image = collection.median();
    // Calculate NDWI for Sentinel-2: (B3 - B8)/(B3 + B8)
    const ndwi = image.normalizedDifference(['B3', 'B8']);
    const water = ndwi.gt(0.0);
    return water;
  }

  // Get water masks for both periods
  const water2021 = getWaterArea(sept2021, '2021');
  const water2023 = getWaterArea(sept2023, '2023');

  // Check for empty collections
  if (!water2021 || !water2023) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate water areas
  function calculateWaterArea(waterMask, year) {
    const areaStats = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: memphisArea,
      scale: 100,
      maxPixels: 1e9
    });

    const pixelCount = areaStats.getInfo()['nd'];
    if (pixelCount === null || pixelCount === undefined) {
      console.log(`${year} No valid pixels`);
      return null;
    }

    const areaSqKm = (pixelCount * 100 * 100) / 1e6; // Convert to km²
    console.log(`${year} Water Pixels: ${pixelCount}, Area: ${areaSqKm.toFixed(2)} km²`);
    return areaSqKm;
  }

  const area2021 = calculateWaterArea(water2021, '2021');
  const area2023 = calculateWaterArea(water2023, '2023');

  // 4. Validation & Final Answer
  if (area2021 === null || area2023 === null) {
    console.log("<answer>C2</answer>");
  } else if (isNaN(area2021) || isNaN(area2023) || area2021 < 0 || area2023 < 0) {
    console.log("<answer>C3</answer>");
  } else {
    const change = ((area2023 - area2021) / area2021 * 100).toFixed(1);
    console.log(`Change: ${change}%`);

    if (area2023 < area2021) {
      console.log("<answer>A</answer>");
    } else {
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
